CREATE OR REPLACE FUNCTION public.analysis_drill_safety_revision(p_user uuid,p_date date) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('context',(SELECT to_jsonb(c) FROM public.athlete_context c WHERE user_id=p_user),'profile',(SELECT jsonb_build_object('dob',date_of_birth,'positions',positions,'hammers_today_started_at',hammers_today_started_at) FROM public.profiles WHERE id=p_user),'settings',(SELECT to_jsonb(s) FROM public.athlete_mpi_settings s WHERE user_id=p_user),'timeline',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.created_at) FROM public.schedule_timeline_entries t WHERE user_id=p_user AND undone_at IS NULL),'[]'::jsonb),'heights',coalesce((SELECT jsonb_agg(to_jsonb(h) ORDER BY h.measured_on) FROM public.athlete_height_checks h WHERE user_id=p_user),'[]'::jsonb),'logs',coalesce((SELECT jsonb_agg(to_jsonb(d) ORDER BY d.entry_date) FROM public.athlete_daily_log d WHERE user_id=p_user AND entry_date=p_date),'[]'::jsonb),'gear',coalesce((SELECT jsonb_agg(to_jsonb(g) ORDER BY g.created_at) FROM public.athlete_equipment_context g WHERE user_id=p_user),'[]'::jsonb),'memory',coalesce((SELECT jsonb_agg(to_jsonb(m) ORDER BY m.created_at) FROM public.athlete_equipment_memory m WHERE user_id=p_user AND (scope='always' OR plan_date=p_date)),'[]'::jsonb),'games',coalesce((SELECT jsonb_agg(to_jsonb(g) ORDER BY g.id) FROM public.gp_games g WHERE user_id=p_user AND game_date BETWEEN p_date AND p_date+1),'[]'::jsonb),'calendar',coalesce((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.id) FROM public.calendar_events e WHERE user_id=p_user AND event_date BETWEEN p_date AND p_date+1),'[]'::jsonb),'arm',coalesce((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.id) FROM public.arm_ledger_entries a WHERE user_id=p_user AND entry_date BETWEEN p_date-365 AND p_date),'[]'::jsonb),'subscription',coalesce((SELECT jsonb_agg(to_jsonb(s) ORDER BY s.id) FROM public.subscriptions s WHERE user_id=p_user),'[]'::jsonb),'readiness',coalesce((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.occurred_at,e.event_id) FROM public.asb_events e WHERE athlete_id=p_user AND topic_id='behavioral.readiness' AND occurred_at>=p_date::timestamptz AND occurred_at<(p_date+1)::timestamptz),'[]'::jsonb)); $$;
REVOKE ALL ON FUNCTION public.analysis_drill_safety_revision(uuid,date) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.analysis_drill_safety_revision(uuid,date) TO service_role;